-- Met à jour updated_at à chaque modification
CREATE FUNCTION set_updated_at() RETURNS trigger AS $$
BEGIN
    NEW.updated_at := now();
    RETURN NEW;
END;
$$ LANGUAGE plpgsql;

CREATE TRIGGER trg_users_updated
  BEFORE UPDATE ON users
  FOR EACH ROW EXECUTE FUNCTION set_updated_at();

-- Stocker et interroger du JSON, avec index GIN
CREATE TABLE events (id uuid PRIMARY KEY DEFAULT uuidv7(), payload jsonb);
CREATE INDEX idx_events_payload ON events USING GIN (payload);

SELECT id FROM events
WHERE payload @> '{"type": "login"}'      -- contient
  AND payload->>'ip' LIKE '10.%';         -- extraction de champ
